<template>
  <div class="mobile-image-to-image-config">
    <!-- 上传区域 -->
    <div class="upload-section">
      <mobile-image-uploader
        ref="imageUploaderRef"
        @on-upload-success="onImageUploadSuccess"
        @on-upload-remove="onImageUploadRemove"
      />
    </div>

    <!-- 提示词输入区域 -->
    <div class="prompt-section">
      <div class="prompt-label">{{ $t('prompt') }}</div>
      <div class="prompt-input-container">
        <textarea 
          v-model="promptText"
          class="prompt-textarea"
          :placeholder="$t('enterPromptToGenerateImage')"
          rows="4"
          @input="onPromptChange"
        />
      </div>
      <div class="random-button-container">
        <button class="random-button" @click="generateRandomSeed">
            <mobile-l-img src='/static/mobile_images/refresh-icon-blue.png' w="10px" h="10px"/>
            <span class="random-text">{{ $t('random') }}</span>
          </button>
    </div>
    </div>

    

    <!-- 种子输入区域 -->
    <div class="seed-section">
      <div class="seed-label">{{ $t('seedOptional') }}</div>
      <div class="seed-input-container">
        <div class="seed-input-wrapper">
          <input 
            v-model="seedNumber"
            type="text"
            class="seed-input"
            :placeholder="$t('enterSeedNumber')"
            @input="onSeedChange"
          />
          
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import MobileImageUploader from '@/mobile/components/mobile-image-uploader.vue';

// props区域
const props = defineProps({
  promptText: {
    type: String,
    default: ''
  },
  seedNumber: {
    type: String,
    default: ''
  }
});

// emits区域
const emit = defineEmits(['onPromptChange', 'onSeedChange', 'onImageUploadSuccess', 'onImageUploadRemove']);

// 变量区域
const { t } = useI18n();

// 响应式变量
const promptText = ref(props.promptText);
const seedNumber = ref(props.seedNumber);
const imageUploaderRef = ref(null);

// watch区域
watch(() => props.promptText, (newValue) => {
  promptText.value = newValue;
});

watch(() => props.seedNumber, (newValue) => {
  seedNumber.value = newValue;
});

// 自定义事件区域
const onPromptChange = () => {
  emit('onPromptChange', promptText.value);
};

const onSeedChange = () => {
  emit('onSeedChange', seedNumber.value);
};

const onImageUploadSuccess = (result) => {
  emit('onImageUploadSuccess', result);
};

const onImageUploadRemove = () => {
  emit('onImageUploadRemove');
};

// 点击事件区域
const generateRandomSeed = () => {
  console.log('generateRandomSeed');
};

// 导出区域
defineExpose({
  reset: () => {
    promptText.value = '';
    seedNumber.value = '';
    if (imageUploaderRef.value) {
      imageUploaderRef.value.reset();
    }
  },
  getFormData: () => ({
    prompt: promptText.value,
    seed: seedNumber.value,
    image: imageUploaderRef.value?.getCurrentImage() || null
  })
});
</script>

