<template>
  <div class="mobile-image-to-image-bottom-config-wrapper">
    <div class="mobile-image-to-image-bottom-config-container">
      <!-- 质量选择区域 -->
      <div class="quality-selector-section">
        <mobile-dropdown 
          :model-value="selectedQuality" 
          :options="qualityOptions" 
          :placeholder="$t('selectQuality')"
          theme="light" 
          direction="up"
          @onChange="onQualityChange" 
        />
      </div>

      <!-- 强度滑块区域 -->
      <div class="strength-slider-section">
        <mobile-slider
          v-model="strengthValue"
          :min="0"
          :max="1"
          :step="0.1"
          :precision="1"
          :show-current-value="true"
          trigger-text="Strength"
          unit=""
          @onChange="onStrengthChange"
        />
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileDropdown from '@/mobile/components/mobile-dropdown.vue';
import MobileSlider from '@/mobile/components/mobile-slider.vue';

// props区域
const props = defineProps({
  selectedQuality: {
    type: String,
    default: 'standard'
  },
  qualityOptions: {
    type: Array,
    default: () => []
  },
  selectedStrength: {
    type: Number,
    default: 0.9
  }
});

// emits区域
const emit = defineEmits(['onQualityChange', 'onStrengthChange']);

// 变量区域
const { t } = useI18n();

// 响应式变量
const strengthValue = ref(props.selectedStrength);

// watch区域
watch(() => props.selectedStrength, (newValue) => {
  strengthValue.value = newValue;
});

// 自定义事件区域
const onQualityChange = (option) => {
  console.log('质量变更:', option);
  emit('onQualityChange', option);
};

const onStrengthChange = (value) => {
  console.log('强度变更:', value);
  emit('onStrengthChange', value);
};

// 导出区域
defineExpose({
  reset: () => {
    emit('onQualityChange', { value: 'standard' });
    strengthValue.value = 0.9;
    emit('onStrengthChange', 0.9);
  }
});
</script>

