<template>
  <div class="mobile-video-quality-selector-wrapper">
    <div class="mobile-video-quality-selector-container">
      <!-- 质量选择区域 -->
      <div class="quality-selector-section">
        <mobile-dropdown 
          :model-value="selectedQuality" 
          :options="qualityOptions" 
          :placeholder="$t('selectQuality')"
          theme="light" 
          direction="up"
          @onChange="onQualityChange" 
        />
      </div>

      <!-- 时长选择区域 -->
      <div class="duration-selector-section">
        <mobile-dropdown 
          :model-value="selectedDuration" 
          :options="durationOptions" 
          :placeholder="$t('duration')"
          theme="light" 
          direction="up"
          @onChange="onDurationChange" 
        />
      </div>

      <!-- 纵横比选择区域 -->
      <div class="aspect-ratio-selector-section">
        <mobile-dropdown 
          :model-value="selectedAspectRatio" 
          :options="aspectRatioOptions"
          :placeholder="$t('selectAspectRatio')" 
          theme="light" 
          direction="up"
          @onChange="onAspectRatioChange"
        >
          <template #option="{ option, isSelected }">
            <div class="aspect-ratio-option">
              <div class="aspect-ratio-option-content">
                <div 
                  class="ratio-preview"
                  :style="getRatioStyle(option.label)"
                ></div>
              </div>
              
              <span class="ratio-label" :class="{ 'selected': isSelected }">{{ option.label }}</span>
            </div>
          </template>
        </mobile-dropdown>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileDropdown from '@/mobile/components/mobile-dropdown.vue';

// props区域
const props = defineProps({
  selectedQuality: {
    type: String,
    default: 'standard' // 与PC端保持一致：Standard, HD, Ultra HD
  },
  selectedDuration: {
    type: String,
    default: '5s'
  },
  selectedAspectRatio: {
    type: String,
    default: '9:16'
  },
  qualityOptions: {
    type: Array,
    default: () => []
  },
  durationOptions: {
    type: Array,
    default: () => []
  },
  aspectRatioOptions: {
    type: Array,
    default: () => []
  }
});

// emits区域
const emit = defineEmits(['onQualityChange', 'onDurationChange', 'onAspectRatioChange']);

// 变量区域
const { t } = useI18n();

// 自定义事件区域
const onQualityChange = (option) => {
  console.log('质量变更:', option);
  emit('onQualityChange', option);
};

const onDurationChange = (option) => {
  console.log('时长变更:', option);
  emit('onDurationChange', option);
};

const onAspectRatioChange = (option) => {
  console.log('纵横比变更:', option);
  emit('onAspectRatioChange', option);
};

// 数据解析区域
// 计算比例图形样式 - 复用自quality-selector.vue
const getRatioStyle = (ratioLabel) => {
  const containerSize = 20; // 容器尺寸
  const [width, height] = ratioLabel.split(':').map(Number);
  const aspectRatio = width / height;
  
  let finalWidth, finalHeight;
  if (aspectRatio >= 1) {
    // 宽度较大的比例
    finalWidth = containerSize;
    finalHeight = containerSize / aspectRatio;
  } else {
    // 高度较大的比例
    finalHeight = containerSize;
    finalWidth = containerSize * aspectRatio;
  }
  
  return {
    width: `${Math.max(finalWidth, 6)}px`,
    height: `${Math.max(finalHeight, 6)}px`
  };
};

// 导出区域
defineExpose({
  reset: () => {
    emit('onQualityChange', { value: 'standard' }); // 与PC端保持一致
    emit('onDurationChange', { value: '5s' });
    emit('onAspectRatioChange', { value: '9:16' });
  }
});
</script>

