<template>
  <div class="mobile-parameter-config">
    <!-- Prompt 输入区域 -->
    <div class="prompt-input-section">
      <p class="input-label">{{ $t('prompt') }}</p> <!-- Prompt -->
      <div class="prompt-input-container">
        <textarea 
          :value="promptText" 
          @input="onPromptInput"
          class="prompt-textarea"
          :placeholder="$t('enterPromptPlaceholder')"
        ></textarea> <!-- Enter a prompt to generate an image -->
      </div>
    </div>

    <!-- Seed 输入区域 -->
    <div class="seed-input-section">
      <p class="input-label">{{ $t('seedOptional') }}</p> <!-- Seed(Optional) -->
      <div class="seed-input-container">
        <input 
          :value="seedNumber" 
          @input="onSeedInput"
          type="number" 
          class="seed-input" 
          :placeholder="$t('enterSeedNumber')" 
        />
        <!-- Enter seed number -->
      </div>
    </div>
  </div>
</template>

<script setup>
import { useI18n } from 'vue-i18n';

// props区域
const props = defineProps({
  promptText: {
    type: String,
    default: ''
  },
  seedNumber: {
    type: [String, Number],
    default: ''
  }
});

// emits区域
const emit = defineEmits(['onPromptChange', 'onSeedChange']);

// 变量区域
const { t } = useI18n();

// 自定义事件区域
const onPromptInput = (event) => {
  const value = event.target.value;
  emit('onPromptChange', value);
};

const onSeedInput = (event) => {
  const value = event.target.value;
  emit('onSeedChange', value);
};

// 导出区域
defineExpose({
  reset: () => {
    emit('onPromptChange', '');
    emit('onSeedChange', '');
  }
});
</script>

