<template>
  <div class="text-to-image-page">

    <!-- 主内容区域 -->
    <div class="main-content">
      <!-- 顶部功能选择区域 -->
      <div class="function-selection-area">
        <!-- Image generation 下拉选择 -->
        <div class="generation-type-selector">
          <mobile-dropdown v-model="selectedGenerationType" :options="generationTypeOptions"
            :placeholder="$t('selectGenerationType')" theme="dark" @onChange="onGenerationTypeChange" />
        </div>

        <!-- 模型选择下拉框 -->
        <div class="model-selector">
          <mobile-dropdown v-model="selectedModel" :options="modelOptions" :placeholder="$t('selectModel')" theme="dark"
            @onChange="onModelChange" />
        </div>
      </div>

      <!-- 分隔线 -->
      <div class="section-divider"></div>

      <!-- Tab栏区域 -->
      <div class="tab-bar-area">
        <div class="tab-container" ref="tabContainer">
          <div v-for="(tab, index) in tabOptions" :key="tab.value" :ref="el => setTabRef(el, index)" class="tab-item"
            :class="{ 'active': activeTab === index }" @click="clickTab(index)">
            <p class="tab-title">{{ tab.label }}</p>
          </div>
        </div>

        <!-- 当前功能下划线 -->
        <div class="tab-underline-container">
          <div class="tab-underline" :style="underlineStyle"></div>
        </div>
      </div>


      <!-- 参数配置区域 - 仅在Image generation并且Text to image时显示 -->
      <text-to-image-config v-if="showParameterConfig" key="text-to-image" ref="parameterConfigRef" :prompt-text="promptText"
        :seed-number="seedNumber" @on-prompt-change="onPromptChange" @on-seed-change="onSeedChange" />

      <!-- Image to image参数配置区域 - 仅在Image generation并且Image to image时显示 -->
      <image-to-image-config v-if="showImageToImageConfig" key="image-to-image" ref="imageToImageConfigRef" :prompt-text="promptText"
        :seed-number="seedNumber" @on-prompt-change="onPromptChange" @on-seed-change="onSeedChange"
        @on-image-upload-success="onImageUploadSuccess" @on-image-upload-remove="onImageUploadRemove" />

      <!-- Text to video参数配置区域 - 仅在Video generation并且Text to video时显示 -->
      <text-to-image-config v-if="showTextToVideoConfig" key="text-to-video" ref="textToVideoConfigRef" :prompt-text="promptText"
        :seed-number="seedNumber" @on-prompt-change="onPromptChange" @on-seed-change="onSeedChange" />

      <!-- Picture to video参数配置区域 - 复用图生图组件 -->
      <image-to-image-config v-if="showPictureToVideoConfig" key="picture-to-video" ref="pictureToVideoConfigRef" :prompt-text="promptText"
        :seed-number="seedNumber" @on-prompt-change="onPromptChange" @on-seed-change="onSeedChange"
        @on-image-upload-success="onImageUploadSuccess" @on-image-upload-remove="onImageUploadRemove" />

        <!-- 底部按钮占位区域 -->
      <div class="empty-quality-selector-area"
        :style="{height: showQualitySelectorHeight ? showQualitySelectorHeight+'px' : '0px'}"></div>

        <!-- 按钮功能区 -->
      <div class="quality-selector-area" ref="qualitySelectorAreaRef">
        <!-- 质量选择器区域 - 仅在Image generation并且Text to image时显示 -->
        <quality-selector v-if="showQualitySelector" ref="qualitySelectorRef" :selected-quality="selectedQuality"
          :selected-aspect-ratio="selectedAspectRatio" :quality-options="qualityOptions"
          :aspect-ratio-options="aspectRatioOptions" @on-quality-change="onQualityChange"
          @on-aspect-ratio-change="onAspectRatioChange" />

        <!-- Image to image底部配置区域 - 仅在Image generation并且Image to image时显示 -->
        <image-to-image-bottom-config v-if="showImageToImageBottomConfig" ref="imageToImageBottomConfigRef"
          :selected-quality="selectedQuality" :quality-options="qualityOptions" :selected-strength="selectedStrength"
          @on-quality-change="onQualityChange" @on-strength-change="onStrengthChange" />



        <!-- 视频质量选择器区域 - 仅在Video generation时显示 -->
        <video-quality-selector v-if="showVideoQualitySelector" ref="videoQualitySelectorRef"
          :selected-quality="selectedQuality" :selected-duration="selectedDuration"
          :selected-aspect-ratio="selectedAspectRatio" :quality-options="videoQualityOptions"
          :duration-options="videoDurationOptions" :aspect-ratio-options="videoAspectRatioOptions"
          @on-quality-change="onQualityChange" @on-duration-change="onDurationChange"
          @on-aspect-ratio-change="onAspectRatioChange" />

        <!-- 生成按钮区域 - 始终显示 -->
        <div class="generate-button-wrapper">
          <div class="generate-button-container">
            <button class="generate-button" @click="handleGenerateImage" :disabled="!canGenerate">
              {{ generateButtonText }}
            </button>
          </div>
        </div>
      </div>

    </div>
  </div>
</template>

<script setup>
// 引入区域
import { ref, computed, watch, onMounted, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router';
import MobileDropdown from '@/mobile/components/mobile-dropdown.vue';
import TextToImageConfig from '@/mobile/views/produce-media/text-to-image-config.vue';
import QualitySelector from '@/mobile/views/produce-media/quality-selector.vue';
import ImageToImageConfig from '@/mobile/views/produce-media/image-to-image-config.vue';
import ImageToImageBottomConfig from '@/mobile/views/produce-media/image-to-image-bottom-config.vue';
// TextToVideoConfig 复用 TextToImageConfig 组件
import VideoQualitySelector from '@/mobile/views/produce-media/video-quality-selector.vue';
import { resolutionOptions, imageAllRatioOptions, durationOptions, videoAllRatioOptions } from '@/types/panel-options';
import { useChatModelStore } from '@/store/modules/chat-model';
import { ApiGeneration } from '@/api/api-generation';
import { MediaTaskPolling, TaskType } from '@/presenter/media-task-polling';
import { ROUTER_PATHS } from '@/router/constants';
import { showMessageWarning, showMessageError } from '@/utils/mobile-ui-feedback';

// props区域

// emits区域 - 移除所有emit
// const emit = defineEmits(['onGenerationTypeChange', 'onModelChange', 'onGenerate', 'onTabChange']);

// 变量区域
const { t } = useI18n();
const router = useRouter();
const chatModelStore = useChatModelStore();

// 常量
// 状态类型常量
const STATE_TYPES = {
  TEXT_TO_IMAGE: 'text-to-image',
  IMAGE_TO_IMAGE: 'image-to-image',
  TEXT_TO_VIDEO: 'text-to-video',
  PICTURE_TO_VIDEO: 'picture-to-video'
};

// 状态基本定义模板
const STATE_DEFAULTS = {
  [STATE_TYPES.TEXT_TO_IMAGE]: {
    promptText: '',
    seedNumber: '',
    selectedQuality: 'standard',
    selectedAspectRatio: '9:16'
  },
  [STATE_TYPES.IMAGE_TO_IMAGE]: {
    promptText: '',
    seedNumber: '',
    selectedQuality: 'standard',
    selectedAspectRatio: '9:16',
    selectedStrength: 0.9,
    uploadedImage: null
  },
  [STATE_TYPES.TEXT_TO_VIDEO]: {
    promptText: '',
    seedNumber: '',
    selectedQuality: 'standard',
    selectedAspectRatio: '9:16',
    selectedDuration: '5s'
  },
  [STATE_TYPES.PICTURE_TO_VIDEO]: {
    promptText: '',
    seedNumber: '',
    selectedQuality: 'standard',
    selectedAspectRatio: '9:16',
    selectedDuration: '5s',
    uploadedImage: null
  }
};

// 创建初始状态数据
const createInitialStateData = () => {
  const stateData = {};
  Object.keys(STATE_DEFAULTS).forEach(key => {
    stateData[key] = { ...STATE_DEFAULTS[key] };
  });
  return stateData;
};

// 响应式变量
const selectedGenerationType = ref('image-generation');
const selectedModel = ref('');
const activeTab = ref(0); // 当前激活的tab下标

// 四个状态的独立数据存储
const stateData = ref(createInitialStateData());

const qualitySelectorAreaRef = ref(null);

// Tab相关引用
const tabContainer = ref(null);
const tabRefs = ref([]);
const underlineWidth = ref(0);
const underlineLeft = ref(0);

// 子组件引用
const parameterConfigRef = ref(null);
const qualitySelectorRef = ref(null);
const imageToImageConfigRef = ref(null);
const imageToImageBottomConfigRef = ref(null);
const textToVideoConfigRef = ref(null);
const pictureToVideoConfigRef = ref(null);
const videoQualitySelectorRef = ref(null);

// 下拉选项数据
const generationTypeOptions = ref([
  { value: 'image-generation', label: t('imageGeneration') },
  { value: 'video-generation', label: t('videoGeneration') }
]);

const modelOptions = ref([]);
const qualityOptions = ref(resolutionOptions);
const aspectRatioOptions = ref(imageAllRatioOptions);

// 视频相关选项数据 - 与PC端保持一致
const videoQualityOptions = ref(resolutionOptions); // 使用相同的清晰度选项：Standard, HD, Ultra HD
const videoDurationOptions = ref(durationOptions);
const videoAspectRatioOptions = ref(videoAllRatioOptions);

// Tab选项数据 - 根据生成类型动态变化
const imageGenerationTabs = [
  { value: 'text-to-image', label: t('textToImage') },
  { value: 'image-to-image', label: t('imageToImage') }
];

const videoGenerationTabs = [
  { value: 'text-to-video', label: t('textToVideo') },
  { value: 'picture-to-video', label: t('pictureToVideo') }
];

const tabOptions = ref(imageGenerationTabs);

// 计算属性区域
// 获取当前激活tab的信息
const currentTab = computed(() => {
  return tabOptions.value[activeTab.value] || tabOptions.value[0];
});

// 获取当前状态的数据
const currentStateData = computed(() => {
  const tabValue = currentTab.value?.value;
  return tabValue ? stateData.value[tabValue] : {};
});

// 当前状态的数据访问器
const promptText = computed(() => currentStateData.value.promptText || '');
const seedNumber = computed(() => currentStateData.value.seedNumber || '');
const selectedQuality = computed(() => currentStateData.value.selectedQuality || 'standard');
const selectedAspectRatio = computed(() => currentStateData.value.selectedAspectRatio || '9:16');
const selectedStrength = computed(() => currentStateData.value.selectedStrength || 0.9);
const selectedDuration = computed(() => currentStateData.value.selectedDuration || '5s');
const uploadedImage = computed(() => currentStateData.value.uploadedImage || null);

const canGenerate = computed(() => {
  const hasPrompt = promptText.value.trim().length > 0;
  
  switch (currentTab.value?.value) {
    case STATE_TYPES.IMAGE_TO_IMAGE:
    case STATE_TYPES.PICTURE_TO_VIDEO:
      // 图片相关模式需要额外验证上传的图片
      return hasPrompt && uploadedImage.value !== null;
    
    case STATE_TYPES.TEXT_TO_IMAGE:
    case STATE_TYPES.TEXT_TO_VIDEO:
    default:
      // 文本相关模式只需要验证提示词
      return hasPrompt;
  }
});

// 下划线样式计算
const underlineStyle = computed(() => {
  return {
    width: `${underlineWidth.value}px`,
    transform: `translateX(${underlineLeft.value}px)`,
    transition: 'all 0.3s ease'
  };
});

// 控制组件显示的计算属性
const showParameterConfig = computed(() => {
  return selectedGenerationType.value === 'image-generation' && 
         currentTab.value && 
         currentTab.value.value === STATE_TYPES.TEXT_TO_IMAGE;
});

const showQualitySelector = computed(() => {
  return selectedGenerationType.value === 'image-generation' && 
         currentTab.value && 
         currentTab.value.value === STATE_TYPES.TEXT_TO_IMAGE;
});

const showImageToImageConfig = computed(() => {
  return selectedGenerationType.value === 'image-generation' && 
         currentTab.value && 
         currentTab.value.value === STATE_TYPES.IMAGE_TO_IMAGE;
});

const showImageToImageBottomConfig = computed(() => {
  return selectedGenerationType.value === 'image-generation' && 
         currentTab.value && 
         currentTab.value.value === STATE_TYPES.IMAGE_TO_IMAGE;
});

const showTextToVideoConfig = computed(() => {
  return selectedGenerationType.value === 'video-generation' && 
         currentTab.value && 
         currentTab.value.value === STATE_TYPES.TEXT_TO_VIDEO;
});

const showPictureToVideoConfig = computed(() => {
  return selectedGenerationType.value === 'video-generation' && 
         currentTab.value && 
         currentTab.value.value === STATE_TYPES.PICTURE_TO_VIDEO;
});

const showVideoQualitySelector = computed(() => {
  return selectedGenerationType.value === 'video-generation' && 
         currentTab.value && 
         (currentTab.value.value === STATE_TYPES.TEXT_TO_VIDEO || currentTab.value.value === STATE_TYPES.PICTURE_TO_VIDEO);
});

const generateButtonText = computed(() => {
  return selectedGenerationType.value === 'video-generation' 
    ? t('generateVideo') 
    : t('generateImage');
});

const showQualitySelectorHeight = computed(() => {
  return qualitySelectorAreaRef.value ? qualitySelectorAreaRef.value.offsetHeight : 0;
});

// 点击事件区域
const handleGenerateImage = async () => {
  if (!canGenerate.value) return;

  const tabValue = currentTab.value?.value;
  const currentData = stateData.value[tabValue] || {};

  try {
    
    // 根据当前tab决定调用哪个API
    let apiParams = {};
    let apiMethod = null;
    let taskType = TaskType.IMAGE;

    switch (tabValue) {
      case STATE_TYPES.TEXT_TO_IMAGE:
        // 文生图 - 只传入新接口需要的字段
        taskType = TaskType.IMAGE;
        
        apiParams = {
          prompt: (currentData.promptText || '').trim(),
          negative_prompt: '', // 负面提示词
          model: selectedModel.value
        };

        // 只有XMIND-G-IMAGEN-3模型时才传入aspect_ratio
        if (selectedModel.value === 'XMIND-G-IMAGEN-3') {
          apiParams.aspect_ratio = currentData.selectedAspectRatio || '9:16';
        }
        apiMethod = 'textToImage';
        break;

      case STATE_TYPES.IMAGE_TO_IMAGE:
        // 图生图 - 暂不支持
        console.warn('Image to image mode is not supported yet');
        showMessageWarning(t('featureComingSoon') || 'Feature coming soon');
        return;

      case STATE_TYPES.TEXT_TO_VIDEO:
        // 文生视频 - 参数与PC端保持一致
        taskType = TaskType.VIDEO;
        const aspectRatio = currentData.selectedAspectRatio || '9:16';
        
        apiParams = {
          prompt: (currentData.promptText || '').trim(),
          model: selectedModel.value,
          duration: parseInt((currentData.selectedDuration || '5s').replace('s', '')),
          aspect_ratio: aspectRatio,
          negative_prompt: '' // 固定传空字符串
        };
        apiMethod = 'textToVideo';
        break;

      case STATE_TYPES.PICTURE_TO_VIDEO:
        // 图生视频 - 参数与PC端保持一致
        taskType = TaskType.VIDEO;
        
        if (!currentData.uploadedImage) {
          console.warn('Picture to video mode requires an uploaded image');
          showMessageWarning(t('pleaseUploadImage') || 'Please upload an image first');
          return;
        }
        
        const picToVideoAspectRatio = currentData.selectedAspectRatio || '9:16';
        
        // 处理图片URL - 确保包含完整的OSS路径
        const baseUrl = process.env.VITE_APP_OSS_PIC_PATH || '';
        const imageUrl = currentData.uploadedImage.url || currentData.uploadedImage;
        const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : baseUrl + imageUrl;
        
        apiParams = {
          source_image_url: fullImageUrl,
          prompt: (currentData.promptText || '').trim(),
          model: selectedModel.value,
          duration: parseInt((currentData.selectedDuration || '5s').replace('s', '')),
          aspect_ratio: picToVideoAspectRatio,
          negative_prompt: '' // 固定传空字符串
        };
        apiMethod = 'imageToVideo';
        break;

      default:
        console.warn('Unknown tab value:', tabValue);
        showMessageError(t('invalidOperation') || 'Invalid operation');
        return;
    }

    
    // 创建API实例并调用对应方法
    const apiGeneration = new ApiGeneration();
    const result = await apiGeneration[apiMethod](apiParams);
    
    
    // 添加任务到轮询队列
    MediaTaskPolling.addTask(result.task_id, taskType);
    
    // 在新页面中打开结果页面并传递task_id参数
    const resultPath = taskType === TaskType.VIDEO 
      ? ROUTER_PATHS.MOBILE_VIDEO_RESULT 
      : ROUTER_PATHS.MOBILE_IMAGE_RESULT;
    
    // 构建完整的URL
    const baseUrl = window.location.origin;
    const queryParams = new URLSearchParams({
      type: selectedGenerationType.value,
      tab: tabValue
    });
    const fullUrl = `${baseUrl}${resultPath}/${result.task_id}?${queryParams.toString()}`;
    
    // 在新窗口/标签页中打开结果页面
    window.open(fullUrl, '_blank');
    
  } catch (error) {
    console.error('生成任务失败:', error);
    showMessageError(t('generateFailed') || 'Generation failed');
  }
};

// Tab切换事件
const clickTab = (index) => {
  if (activeTab.value !== index) {
    activeTab.value = index;
    const tab = tabOptions.value[index];
    
    // 清空当前选中的模型，让用户重新选择
    selectedModel.value = '';
    
    // Tab切换不再直接影响生成类型，只是在当前生成类型下切换具体功能
    // emit('onTabChange', {
    //   activeTab: tab.value,
    //   generationType: selectedGenerationType.value
    // });
    
    // 不在这里调用updateUnderlinePosition，让watch(activeTab)统一处理
  }
};

// 数据更新辅助函数
const updateCurrentStateData = (key, value) => {
  const tabValue = currentTab.value?.value;
  if (tabValue && stateData.value[tabValue]) {
    stateData.value[tabValue][key] = value;
  }
};

// 重置所有状态数据
const resetAllStates = () => {
  stateData.value = createInitialStateData();
};

// 自定义事件区域
const onGenerationTypeChange = (option) => {

  // 移除 emit('onGenerationTypeChange', option);

  // 根据生成类型更新Tab选项
  if (option.value === 'video-generation') {
    tabOptions.value = videoGenerationTabs;
    activeTab.value = 0; // 设置默认激活第一个tab

  } else {
    tabOptions.value = imageGenerationTabs;
    activeTab.value = 0; // 设置默认激活第一个tab

  }
  
  // 清空当前选中的模型，让用户重新选择
  selectedModel.value = '';
  
  // 清空旧的引用，让watch(tabOptions)处理下划线位置更新
  tabRefs.value = [];
};

const onModelChange = (option) => {

  // 移除 emit('onModelChange', option);
};

const onQualityChange = (option) => {
  updateCurrentStateData('selectedQuality', option.value);

};

const onAspectRatioChange = (option) => {
  updateCurrentStateData('selectedAspectRatio', option.value);

};

const onDurationChange = (option) => {
  updateCurrentStateData('selectedDuration', option.value);

};

// 新增事件处理函数
const onPromptChange = (value) => {
  updateCurrentStateData('promptText', value);
};

const onSeedChange = (value) => {
  updateCurrentStateData('seedNumber', value);
};

const onStrengthChange = (value) => {
  updateCurrentStateData('selectedStrength', value);

};

const onImageUploadSuccess = (result) => {
  updateCurrentStateData('uploadedImage', result);

};

const onImageUploadRemove = () => {
  updateCurrentStateData('uploadedImage', null);

};

// 数据解析区域
const getQualityLabel = (qualityValue) => {
  const quality = qualityOptions.value.find(item => item.value === qualityValue);
  return quality ? quality.label : 'Standard';
};

const getAspectRatioLabel = (ratioValue) => {
  const ratio = aspectRatioOptions.value.find(item => item.value === ratioValue);
  return ratio ? ratio.label : '9:16';
};



// 设置tab元素引用
const setTabRef = (el, index) => {
  if (el) {
    tabRefs.value[index] = el;
  }
};

// 更新下划线位置和宽度
const updateUnderlinePosition = () => {

  if (!tabContainer.value || tabRefs.value.length === 0) return;
  
  // 直接使用activeTab.value作为索引
  const currentTabEl = tabRefs.value[activeTab.value];
  if (!currentTabEl) return;
  
  const tabRect = currentTabEl.getBoundingClientRect();
  const containerRect = tabContainer.value.getBoundingClientRect();
  
  // 计算下划线宽度为标题宽度的80%
  const titleEl = currentTabEl.querySelector('.tab-title');
  const titleWidth = titleEl ? titleEl.offsetWidth : tabRect.width;
  underlineWidth.value = titleWidth * 0.8;
  
  // 计算下划线左偏移量，使其在标题下方居中
  const tabLeft = tabRect.left - containerRect.left;
  const tabWidth = tabRect.width;
  const titleCenterOffset = (tabWidth - titleWidth) / 2 + titleWidth / 2;
  underlineLeft.value = tabLeft + titleCenterOffset - underlineWidth.value / 2;
};

// 从store加载模型数据 - 根据当前组合状态调用不同函数
const loadMediaModels = async () => {
  try {
    let models = [];
    const generationType = selectedGenerationType.value;
    const tabValue = currentTab.value?.value;
    
    // 根据顶部下拉框和tab的组合调用不同的模型获取函数
    if (generationType === 'image-generation' && tabValue === STATE_TYPES.TEXT_TO_IMAGE) {
      // 文生图
      models = await chatModelStore.getTextToImageModels();
      
    } else if (generationType === 'image-generation' && tabValue === STATE_TYPES.IMAGE_TO_IMAGE) {
      // 图生图  
      models = await chatModelStore.getImageToImageModels();
    } else if (generationType === 'video-generation' && tabValue === STATE_TYPES.TEXT_TO_VIDEO) {
      // 文生视频
      models = await chatModelStore.getTextToVideoModels();
    } else if (generationType === 'video-generation' && tabValue === STATE_TYPES.PICTURE_TO_VIDEO) {
      // 图生视频
      models = await chatModelStore.getPictureToVideoModels();
    } else {
      // 默认使用通用媒体模型
      models = await chatModelStore.getMediaModels();
    }
    
    modelOptions.value = models;
    
    // 设置默认选中第一个模型
    if (models.length > 0 && !selectedModel.value) {
      selectedModel.value = models[0].value;
    }
  } catch (error) {
    console.error('加载模型失败:', error);
  }
};



// watch区域
watch(activeTab, (newValue) => {

  // 当activeTab变化时更新下划线位置
  nextTick(() => {
    updateUnderlinePosition();
  });
});

watch(tabOptions, () => {
  // 当tab选项变化时，重新计算下划线位置
  nextTick(() => {
    updateUnderlinePosition();
  });
}, { deep: true });

// 监听生成类型变化，重新加载模型
watch(selectedGenerationType, () => {
  loadMediaModels();
});

// 监听tab变化，重新加载模型
watch(activeTab, () => {
  loadMediaModels();
});

// 初始化方法区域

// 周期函数区域
onMounted(() => {
  // 加载模型数据
  loadMediaModels();
  
  // 初始化下划线位置
  nextTick(() => {
    updateUnderlinePosition();
  });
});

// 导出区域
defineExpose({
  resetForm: () => {
    // 重置所有状态的数据
    resetAllStates();
    
    // 重置基本状态
    selectedGenerationType.value = 'image-generation';
    selectedModel.value = '';
    tabOptions.value = imageGenerationTabs;
    activeTab.value = 0;
    
    // 重新加载模型
    loadMediaModels();
    
    // 调用子组件的reset方法
    if (parameterConfigRef.value) {
      parameterConfigRef.value.reset();
    }
    if (qualitySelectorRef.value) {
      qualitySelectorRef.value.reset();
    }
    if (imageToImageConfigRef.value) {
      imageToImageConfigRef.value.reset();
    }
    if (imageToImageBottomConfigRef.value) {
      imageToImageBottomConfigRef.value.reset();
    }
    if (textToVideoConfigRef.value) {
      textToVideoConfigRef.value.reset();
    }
    if (pictureToVideoConfigRef.value) {
      pictureToVideoConfigRef.value.reset();
    }
    if (videoQualitySelectorRef.value) {
      videoQualitySelectorRef.value.reset();
    }
  },
  getFormData: () => {
    const tabValue = currentTab.value?.value;
    const currentData = stateData.value[tabValue] || {};
    
    const baseData = {
      generationType: selectedGenerationType.value,
      model: selectedModel.value,
      prompt: currentData.promptText || '',
      seed: currentData.seedNumber || '',
      quality: currentData.selectedQuality || 'standard',
      activeTab: tabValue || ''
    };

    // 根据当前tab添加特定数据
    switch (tabValue) {
      case STATE_TYPES.TEXT_TO_IMAGE:
        baseData.aspectRatio = currentData.selectedAspectRatio || '9:16';
        break;
        
      case STATE_TYPES.IMAGE_TO_IMAGE:
        baseData.strength = currentData.selectedStrength || 0.9;
        baseData.aspectRatio = currentData.selectedAspectRatio || '9:16';
        baseData.uploadedImage = currentData.uploadedImage || null;
        break;
        
      case STATE_TYPES.TEXT_TO_VIDEO:
        baseData.duration = currentData.selectedDuration || '5s';
        baseData.aspectRatio = currentData.selectedAspectRatio || '9:16';
        break;
        
      case STATE_TYPES.PICTURE_TO_VIDEO:
        baseData.duration = currentData.selectedDuration || '5s';
        baseData.aspectRatio = currentData.selectedAspectRatio || '9:16';
        baseData.uploadedImage = currentData.uploadedImage || null;
        break;
    }

    return baseData;
  },
  switchTab: (tabValue) => {
    const tabIndex = tabOptions.value.findIndex(t => t.value === tabValue);
    if (tabIndex !== -1) {
      clickTab(tabIndex);
    }
  },
  switchGenerationType: (type) => {
    selectedGenerationType.value = type;
    // 触发change事件来更新tab选项
    const option = generationTypeOptions.value.find(opt => opt.value === type);
    if (option) {
      onGenerationTypeChange(option);
    }
  }
});
</script>

